def roman_to_int(s: str) -> int:
    values = {
        'M': 1000, 'CM': 900, 'D': 500, 'CD': 400,
        'C': 100, 'XC': 90, 'XL': 40, 'XX': 30, 'X': 10,
        'IX': 9, 'VIII': 8, 'VII': 7, 'VI': 6, 'V': 5,
        'IV': 4, 'III': 3, 'II': 2, 'I': 1
    }
    total = 0
    i = 0
    while i < len(s):
        current = values[s[i]]
        if i + 1 < len(s) and s[i] in ('M', 'CM', 'D', 'CD', 'XC', 'XL', 'IX'):
            total += current + values[s[i + 1]]
            i += 1
        else:
            total += current
        i += 1
    return total
```

