def is_valid_ipv4(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if part[0] == '0' and len(part) > 1:
            return False
        if int(part) not in range(0, 256):
            return False
    return True
```

